{
  "units": [
    {
      "quote": "A limited-validity passport using endorsement 46 should be issued when the medical circumstance that requires eyeglasses is temporary and the applicant has urgent or emergency travel.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When the medical circumstance requiring eyeglasses is temporary and the applicant has urgent or emergency travel, a limited-validity passport using endorsement 46 should be issued."
    },
    {
      "quote": "The applicant’s expression should be natural.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In passport photos, the applicant's facial expression should be natural."
    },
    {
      "quote": "Normal, unexaggerated smiles are acceptable,",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Normal, unexaggerated smiles are acceptable in passport photographs."
    },
    {
      "quote": "unusual expressions and squinting are not.",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "Unusual facial expressions and squinting are not acceptable in passport photographs."
    },
    {
      "quote": "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Provides factual context that applicants with physical or mental disabilities (such as loss of muscle control from age-related degeneration or medical conditions like Bell's Palsy) may be unable to make a natural or unexaggerated expression."
    },
    {
      "quote": "You may accept a photograph without a natural or unexaggerated expression in these circumstances.",
      "scope_quotes": [
        "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression."
      ],
      "kind": "permission",
      "meaning": "Passport personnel may accept a photograph lacking a natural or unexaggerated expression when the applicant has physical or mental disabilities, including loss of muscle control."
    },
    {
      "quote": "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1).",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "Both of the applicant's eyes should be visible and open in the photograph, subject to cross-referenced infant exceptions."
    },
    {
      "quote": "If the applicant is unable to open one or both eyes because of a medical condition, you may accept the photograph.",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Personnel are permitted to accept the photograph if the applicant cannot open one or both eyes due to a medical condition."
    },
    {
      "quote": "In rare cases, if it is unlikely that the closed eye(s) or exaggerated expression are because of a medical condition, you should request a medical statement signed by a medical professional/health practitioner.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In rare instances where it is unlikely that closed eye(s) or an exaggerated expression stem from a medical condition, personnel should request a signed medical statement from a medical professional or health practitioner."
    },
    {
      "quote": "Processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer applications without photographs to their supervisor for guidance on processing passport applications received without photographs;",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "recommendation",
      "meaning": "When applications are received without photographs, processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer them to their supervisor for processing guidance."
    },
    {
      "quote": "You must not accept a form DS-11 or form DS-82 received without a photograph at the public counter.",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "prohibition",
      "meaning": "A form DS-11 or form DS-82 that is received without a photograph must not be accepted at the public counter."
    },
    {
      "quote": "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility.",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any form DS-11 received from an acceptance facility without an accompanying photograph."
    },
    {
      "quote": "The applicant must re-execute the form DS-11 (see IRL 975-04);",
      "scope_quotes": [
        "Applications received without photographs:",
        "Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility."
      ],
      "kind": "requirement",
      "meaning": "When a form DS-11 is received without a photograph from an acceptance facility, the applicant must re-execute the form DS-11."
    },
    {
      "quote": "Passport specialists must suspend a form DS-82 or form DS-5504 received without a photograph (see IRL 1000-05 and IRL 1018-14).",
      "scope_quotes": [
        "Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend a form DS-82 or form DS-5504 if received without a photograph."
    }
  ]
}
